import json
import itertools
import sys
from pathlib import Path

import problems
from sat_solver import sat_satisfiable, threesat_satisfiable
from reduce import reduce as reduce_fn


def generate_instances(max_vars=3, max_clauses=3):
    # generate all possible literals for given max_vars
    for num_vars in range(0, max_vars + 1):
        literals = [i for i in range(-num_vars, num_vars + 1) if i != 0]
        # generate all possible clauses up to length max_vars (including empty)
        # we allow duplicates and any order per definition.
        clause_options = []
        for length in range(0, max_vars + 1):
            # product with replacement to allow repeats
            clause_options.extend(itertools.product(literals, repeat=length))
        # now generate sets of clauses (list) up to max_clauses
        for clause_count in range(0, max_clauses + 1):
            for clauses in itertools.product(clause_options, repeat=clause_count):
                # convert each clause tuple to list
                instance = {
                    "num_vars": num_vars,
                    "clauses": [list(c) for c in clauses],
                }
                yield instance


def main():
    total = 0
    passed = 0
    for instance in generate_instances():
        total += 1
        # Validate source instance
        try:
            problems.Sat.validate(instance)
        except Exception as e:
            # skip malformed (shouldn't happen)
            continue
        # Compute answer for source
        src_ans = sat_satisfiable(instance)
        # Reduce
        try:
            red = reduce_fn(instance)
        except Exception as e:
            print("Reduction raised exception", e, file=sys.stderr)
            continue
        # Validate target format
        try:
            problems.ThreeSat.validate(red)
        except Exception as e:
            print("Target validation failed", e, file=sys.stderr)
            continue
        # Compute answer for reduced instance
        tgt_ans = threesat_satisfiable(red)
        if src_ans == tgt_ans:
            passed += 1
        else:
            print("Mismatch!", instance, red, src_ans, tgt_ans, file=sys.stderr)
    verdict = {
        "verified": passed == total,
        "tests_run": total,
        "tests_passed": passed,
    }
    Path("verdict.json").write_text(json.dumps(verdict, indent=2))
    print(json.dumps(verdict))

if __name__ == "__main__":
    main()
EOF"}

